<?php
require_once __DIR__.'/_header.php';
$pdo=db();$id=(int)($_GET['id']??0);$st=$pdo->prepare('SELECT s.*,v.title video_title FROM stream_links s JOIN videos v ON v.id=s.video_id WHERE s.id=?');$st->execute([$id]);$s=$st->fetch();if(!$s){http_response_code(404);exit('Stream not found');}
$msg='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$label=trim($_POST['label']??'Stream');$url=trim($_POST['url']??'');$active=isset($_POST['status'])?1:0;if($label===''||!filter_var($url,FILTER_VALIDATE_URL))$msg='Enter a valid label and URL.';else{$pdo->prepare('UPDATE stream_links SET label=?,url=?,status=? WHERE id=?')->execute([$label,$url,$active,$id]);log_action('stream.update','stream_id='.$id);header('Location: video-edit.php?id='.$s['video_id']);exit;}}
?><div class="page-head"><div><h1>Edit Stream Link</h1><p><?=e($s['video_title'])?></p></div></div><?php if($msg):?><p class="error"><?=e($msg)?></p><?php endif;?><form method="post" class="panel" style="padding:22px"><?=csrf_field()?><label>Label<input name="label" value="<?=e($s['label'])?>" required></label><label>Player URL<input name="url" value="<?=e($s['url'])?>" required></label><label class="check"><input type="checkbox" name="status" <?=$s['status']?'checked':''?>> Active</label><button>Save Stream</button> <a class="button secondary" href="video-edit.php?id=<?=$s['video_id']?>">Cancel</a></form><?php require __DIR__.'/_footer.php';